set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/../.." && pwd)"

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

TESTS_PASSED=0
TESTS_FAILED=0

log_pass() {
    echo -e "  ${GREEN}✓${NC} $1"
    TESTS_PASSED=$((TESTS_PASSED + 1))
}

log_fail() {
    echo -e "  ${RED}✗${NC} $1"
    TESTS_FAILED=$((TESTS_FAILED + 1))
}

log_section() {
    echo ""
    echo "═══════════════════════════════════════════════════════════════"
    echo "  $1"
    echo "═══════════════════════════════════════════════════════════════"
}

# Source just the run_with_timeout function from the pre-push hook.
# We extract it to avoid executing the rest of the hook (which needs
# git context, stdin, etc.).
_setup_run_with_timeout() {
    eval "$(sed -n '/^run_with_timeout()/,/^}/p' "${PROJECT_ROOT}/bin/git-hooks/pre-push")"
}

# Test 1: run_with_timeout preserves exit codes
test_run_with_timeout_exit_codes() {
    log_section "Test 1: run_with_timeout preserves exit codes"

    _setup_run_with_timeout

    # Subtest: exit code 0 (success)
    local rc=0
    run_with_timeout 5 true || rc=$?
    if [[ $rc -eq 0 ]]; then
        log_pass "run_with_timeout 5 true returns 0"
    else
        log_fail "run_with_timeout 5 true returned $rc (expected 0)"
    fi

    # Subtest: exit code 1 (failure)
    rc=0
    run_with_timeout 5 false || rc=$?
    if [[ $rc -eq 1 ]]; then
        log_pass "run_with_timeout 5 false returns 1"
    else
        log_fail "run_with_timeout 5 false returned $rc (expected 1)"
    fi

    # Subtest: arbitrary exit code 42
    rc=0
    run_with_timeout 5 bash -c "exit 42" || rc=$?
    if [[ $rc -eq 42 ]]; then
        log_pass "run_with_timeout 5 bash -c 'exit 42' returns 42"
    else
        log_fail "run_with_timeout 5 bash -c 'exit 42' returned $rc (expected 42)"
    fi
}

# Test 2: CHANGELOG variable capture pattern
test_changelog_variable_capture() {
    log_section "Test 2: CHANGELOG variable capture pattern"

    # Subtest: grep finds CHANGELOG.md in captured output
    local _VAR rc
    _VAR=$(echo -e "file1\nCHANGELOG.md\nfile2" || true)
    rc=0
    echo "$_VAR" | grep -q "CHANGELOG.md" || rc=$?
    if [[ $rc -eq 0 ]]; then
        log_pass "Variable capture + grep finds CHANGELOG.md"
    else
        log_fail "Variable capture + grep failed to find CHANGELOG.md (rc=$rc)"
    fi

    # Subtest: grep correctly fails when CHANGELOG.md is absent
    _VAR=$(echo -e "file1\nfile2" || true)
    rc=0
    echo "$_VAR" | grep -q "CHANGELOG.md" || rc=$?
    if [[ $rc -eq 1 ]]; then
        log_pass "Variable capture + grep correctly returns 1 when CHANGELOG.md absent"
    else
        log_fail "Variable capture + grep returned $rc when CHANGELOG.md absent (expected 1)"
    fi
}

# Test 3: run_with_timeout handles arguments with spaces
test_run_with_timeout_spaces() {
    log_section "Test 3: run_with_timeout handles arguments with spaces"

    _setup_run_with_timeout

    local output rc=0
    output=$(run_with_timeout 5 bash -c "echo 'hello world'" 2>&1) || rc=$?
    if [[ $rc -eq 0 && "$output" == "hello world" ]]; then
        log_pass "run_with_timeout handles arguments with spaces"
    else
        log_fail "run_with_timeout with spaces: rc=$rc, output='$output' (expected rc=0, output='hello world')"
    fi
}

# Test 4: Branch-prefix skip regex stays in sync between pre-push hook and CI workflow
# Prevents #1457 ghost-version regressions where one layer skips but the other enforces.
test_skip_regex_parity() {
    log_section "Test 4: Branch-prefix skip regex parity (hook ↔ CI workflow)"

    local hook_file="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local ci_file="${PROJECT_ROOT}/.github/workflows/version-check.yml"

    # Extract the alternation group from each file's skip-list regex.
    local hook_regex ci_regex
    hook_regex=$(grep -oE '\^\([a-z|]+\)/' "$hook_file" | head -1)
    ci_regex=$(grep -oE '\^\([a-z|]+\)/' "$ci_file" | head -1)

    if [[ -z "$hook_regex" ]]; then
        log_fail "Could not extract skip regex from $hook_file"
        return
    fi
    if [[ -z "$ci_regex" ]]; then
        log_fail "Could not extract skip regex from $ci_file"
        return
    fi

    if [[ "$hook_regex" == "$ci_regex" ]]; then
        log_pass "Skip regex matches: $hook_regex"
    else
        log_fail "Skip regex drift! hook: $hook_regex vs CI: $ci_regex"
    fi

    # Subtest: required prefixes are all present (defensive for future edits)
    local required=(docs chore ci style test feat fix perf refactor)
    local missing=()
    for prefix in "${required[@]}"; do
        if [[ "$hook_regex" != *"$prefix"* ]]; then
            missing+=("hook:$prefix")
        fi
        if [[ "$ci_regex" != *"$prefix"* ]]; then
            missing+=("ci:$prefix")
        fi
    done

    if [[ ${#missing[@]} -eq 0 ]]; then
        log_pass "All conventional-commit prefixes present in both regexes"
    else
        log_fail "Missing prefixes: ${missing[*]}"
    fi
}

# Test 5: the hook parses and runs under the bash the shebang actually gets
#
# bin/git-hooks/pre-push declares `#!/bin/bash`. On macOS that is the bundled
# bash 3.2.57, NOT whatever bash 4/5 is on PATH from brew. A bash-4-only
# builtin therefore fails only on the machine the hook actually runs on, and
# Tests 1-4 all passed with `mapfile` live in the discovery block because none
# of them execute or parse the file under /bin/bash.
#
# Every branch below reports the REAL error text rather than discarding it —
# a regression test that hides why it failed just moves the debugging cost.
test_bash32_compatibility() {
    echo ""
    echo "Test 5: pre-push is compatible with /bin/bash (macOS bash 3.2)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"

    # 5a: no bash-4-only builtins outside comments. awk (not grep|grep) so a
    # zero-match result is exit 0 and a real scan failure stays distinguishable.
    local offenders
    offenders=$(awk '
        /^[[:space:]]*#/ { next }
        /(^|[^#[:alnum:]_])(mapfile|readarray)[[:space:]]/ { print NR ": " $0 }
    ' "$hook")
    if [[ -z "$offenders" ]]; then
        log_pass "no mapfile/readarray invocation (bash 4+ builtins)"
    else
        log_fail "bash 4+ builtin in a #!/bin/bash script -> ${offenders}"
    fi

    # 5b: /bin/bash itself must be able to PARSE the hook. Keep the parse error.
    # (see test_resolve_push_branch below for the #3290 refspec regression)
    local parse_err
    if parse_err=$(/bin/bash -n "$hook" 2>&1); then
        log_pass "/bin/bash -n parses the hook"
    else
        log_fail "/bin/bash -n rejected the hook -> ${parse_err}"
    fi

    # 5c: discovery must actually find tests under /bin/bash. This is the
    # assertion that fails loudly on the real bug: with mapfile the array came
    # back empty and the hook exited 1 claiming no tests exist.
    local discover_out
    if discover_out=$(/bin/bash -c '
        cd "$1" || exit 1
        SKIP_UNIT_TESTS=()
        CI_UNIT_TESTS=()
        while IFS= read -r file; do
            [[ -n "$file" ]] || continue
            CI_UNIT_TESTS+=("$file")
        done < <(find tests/unit \( -name "test-*.sh" -o -name "test-*.mjs" \) -type f | sort)
        echo "${#CI_UNIT_TESTS[@]}"
    ' _ "$PROJECT_ROOT" 2>&1); then
        if [[ "$discover_out" =~ ^[0-9]+$ ]] && (( discover_out > 0 )); then
            log_pass "discovery yields ${discover_out} unit tests under /bin/bash"
        else
            log_fail "discovery returned no usable count -> ${discover_out}"
        fi
    else
        log_fail "discovery errored under /bin/bash -> ${discover_out}"
    fi
}

# Test 6: the branch is resolved from the PUSHED refspec, not from HEAD (#3290)
#
# `git rev-parse --abbrev-ref HEAD` returns the literal string "HEAD" in a
# detached worktree, so the conventional-commit prefix exemption never matched
# and the version gate fired on branches that are exempt. Pushing a branch that
# another worktree holds REQUIRES detached HEAD (git refuses one branch in two
# worktrees), so the hook penalised the only safe way to do it.
#
# Sources just resolve_push_branch, the same isolation trick Test 1 uses for
# run_with_timeout, so this never executes the real suite.
test_resolve_push_branch() {
    echo ""
    echo "Test 6: branch resolves from the pushed refspec (#3290)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local fn
    fn=$(sed -n '/^resolve_push_branch()/,/^}/p' "$hook")

    if [[ -z "$fn" ]]; then
        log_fail "resolve_push_branch() not found in the hook — the #3290 fix is gone"
        return
    fi
    log_pass "resolve_push_branch() is present"

    # A real refspec line, exactly what git writes on stdin.
    local got
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'refs/heads/x 1111111 refs/heads/fix/my-branch 2222222')
    if [[ "$got" == "fix/my-branch" ]]; then
        log_pass "refspec on stdin resolves to fix/my-branch"
    else
        log_fail "refspec resolved to '${got}', expected fix/my-branch"
    fi

    # The regression itself: detached HEAD + HEAD:<branch>. The local ref is a
    # SHA (not a branch), which is what made the old code produce "HEAD".
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'3333333 3333333 refs/heads/fix/detached-push 4444444')
    if [[ "$got" == "fix/detached-push" ]]; then
        log_pass "detached-HEAD push resolves to fix/detached-push, not HEAD"
    else
        log_fail "detached push resolved to '${got}', expected fix/detached-push"
    fi

    # A tag-only push must NOT be mistaken for a branch.
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'refs/tags/v1 5555555 refs/tags/v1 6666666')
    if [[ "$got" != "v1" ]]; then
        log_pass "tag refspec does not resolve to a branch name (got '${got}')"
    else
        log_fail "tag refspec was treated as a branch"
    fi

    # Empty stdin must fall back to HEAD so a manual run behaves as before.
    got=$(cd "$PROJECT_ROOT" && bash -c "$fn"$'\n''resolve_push_branch' </dev/null)
    local head_branch
    head_branch=$(cd "$PROJECT_ROOT" && git rev-parse --abbrev-ref HEAD)
    if [[ "$got" == "$head_branch" ]]; then
        log_pass "empty stdin falls back to HEAD (${got})"
    else
        log_fail "empty-stdin fallback gave '${got}', expected '${head_branch}'"
    fi
}

